/* Palette: deep navy background, soft white card, teal accent, warm amber highlight, muted gray text */
:root {
  --bg: #0f172a;
  --card: #f8fafc;
  --accent: #0d9488;
  --accent-dark: #0f766e;
  --highlight: #f59e0b;
  --text: #1e293b;
  --text-muted: #475569;
  --focus: #f59e0b;
  --radius: 16px;
  --shadow: 0 20px 40px rgba(0, 0, 0, 0.35);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 20% 20%, #1e293b, var(--bg));
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  padding: 24px;
}

.meter-card {
  width: 100%;
  max-width: 400px;
  background: var(--card);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 32px 24px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  text-align: center;
}

.meter-title {
  margin: 0;
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--text);
}

.display-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.display-label {
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
}

.display-value {
  font-size: 2.25rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--accent-dark);
  padding: 8px 0;
  border-bottom: 2px solid rgba(13, 148, 136, 0.25);
}

.button-group {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
}

.btn {
  flex: 1 1 120px;
  min-height: 48px;
  padding: 12px 16px;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
  color: #ffffff;
}

.btn-primary {
  background: var(--accent);
}

.btn-primary:hover {
  background: var(--accent-dark);
}

.btn-primary:active {
  transform: translateY(2px);
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.3);
}

.btn-secondary {
  background: var(--text-muted);
}

.btn-secondary:hover {
  background: #334155;
}

.btn-secondary:active {
  transform: translateY(2px);
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.3);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.meter-note {
  margin: 0;
  font-size: 0.875rem;
  color: var(--text-muted);
}

@media (max-width: 400px) {
  .meter-card {
    padding: 24px 16px;
  }
  .display-value {
    font-size: 2rem;
  }
  .btn {
    flex: 1 1 100%;
  }
}

(function () {
  'use strict';

  var MAX_MINUTES = 180;
  var RATE_PER_HOUR = 2.0;

  var paidMinutes = 0;

  var timeDisplay = document.getElementById('time-display');
  var priceDisplay = document.getElementById('price-display');

  function formatTime(minutes) {
    var h = Math.floor(minutes / 60);
    var m = minutes % 60;
    return h + ':' + (m < 10 ? '0' : '') + m;
  }

  function formatPrice(minutes) {
    var price = (minutes / 60) * RATE_PER_HOUR;
    return '$' + price.toFixed(2);
  }

  function render() {
    timeDisplay.textContent = formatTime(paidMinutes);
    priceDisplay.textContent = formatPrice(paidMinutes);
  }

  function addMinutes(amount) {
    paidMinutes = Math.min(paidMinutes + amount, MAX_MINUTES);
    render();
  }

  function clearMeter() {
    paidMinutes = 0;
    render();
  }

  document.getElementById('add-15').addEventListener('click', function () {
    addMinutes(15);
  });

  document.getElementById('add-60').addEventListener('click', function () {
    addMinutes(60);
  });

  document.getElementById('clear').addEventListener('click', clearMeter);

  render();
})();
